package ru.truetv.launcher;
import android.accessibilityservice.*;import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
/** Real service + public Settings window + physical Back filter on a disposable VM. */
public final class ScreenLearningCheck extends Instrumentation {
 private Context c;private HomeActivity home;private RadioScreens screen;private UiAutomation automation;private int checks;private final StringBuilder log=new StringBuilder();private Map<String,?> before;private String beforeServices,beforeEnabled,keyDevice;
 public void onCreate(Bundle b){super.onCreate(b);keyDevice=b.getString("key_device","");start();}private void check(boolean ok,String name){checks++;Bundle progress=new Bundle();progress.putString("check",checks+": "+name+" = "+ok);sendStatus(0,progress);log.append(ok?"PASS ":"FAIL ").append(name).append('\n');if(!ok)throw new AssertionError(name);}private void main(Runnable r){runOnMainSync(r);waitForIdleSync();}interface Condition{boolean ok()throws Exception;}private void until(Condition condition)throws Exception{long end=SystemClock.uptimeMillis()+30000;while(!condition.ok()&&SystemClock.uptimeMillis()<end)Thread.sleep(100);check(condition.ok(),"await condition");}private String shell(String cmd)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(automation.executeShellCommand(cmd))){byte[] b=new byte[1024];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return out.toString("UTF-8").trim();}private Object field(Object owner,String name)throws Exception{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}private ActionSheet sheet()throws Exception{Field f=ActionSheet.class.getDeclaredField("active");f.setAccessible(true);ActionSheet s=(ActionSheet)((java.lang.ref.WeakReference<?>)f.get(null)).get();return s!=null&&s.dialog.isShowing()?s:null;}private boolean focused(String pkg){for(AccessibilityWindowInfo w:automation.getWindows()){AccessibilityNodeInfo root=w.getRoot();if(w.isFocused()&&root!=null&&pkg.contentEquals(root.getPackageName()))return true;}return false;}private boolean active()throws Exception{return ((ScreenLearning)field(ControlService.connected(),"learning")).active();}private void idle()throws Exception{AccessibilityServiceInfo info=ControlService.connected().getServiceInfo();check(info.eventTypes==0&&(info.flags&AccessibilityServiceInfo.FLAG_REQUEST_FILTER_KEY_EVENTS)==0,"capture stops all window observation and Back filtering");}
 private void physicalBack()throws Exception{if(!keyDevice.matches("/dev/input/event[0-9]+"))throw new AssertionError("Explicit disposable keyboard fixture required");shell("sendevent "+keyDevice+" 1 158 1");shell("sendevent "+keyDevice+" 0 0 0");Thread.sleep(120);shell("sendevent "+keyDevice+" 1 158 0");shell("sendevent "+keyDevice+" 0 0 0");}
 public void onStart(){Bundle result=new Bundle();try{c=getTargetContext();check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("Android SDK"),"VM guard");automation=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);AccessibilityServiceInfo info=automation.getServiceInfo();info.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS|AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;automation.setServiceInfo(info);beforeServices=shell("settings get secure enabled_accessibility_services");beforeEnabled=shell("settings get secure accessibility_enabled");SettingsStore prefs=new SettingsStore(c);before=new HashMap<>(prefs.data.getAll());prefs.data.edit().putBoolean("bt_count",false).putBoolean("bt_asked",true).remove("bluetooth_route").remove("wifi_route").commit();shell("settings put secure enabled_accessibility_services ru.truetv.launcher/ru.truetv.launcher.ControlService");shell("settings put secure accessibility_enabled 1");until(()->ControlService.connected()!=null);check((ControlService.connected().getServiceInfo().getCapabilities()&AccessibilityServiceInfo.CAPABILITY_CAN_REQUEST_FILTER_KEY_EVENTS)!=0,"service declares Back-filter capability");home=VmWindows.home(this);until(()->home.hasWindowFocus());idle();ResolveInfo resolved=c.getPackageManager().resolveActivity(new Intent(android.provider.Settings.ACTION_SETTINGS),PackageManager.MATCH_DEFAULT_ONLY);ComponentName target=new ComponentName(resolved.activityInfo.packageName,resolved.activityInfo.name);
 for(int round=0;round<3;round++){final boolean wifi=round==2,save=round!=0;String key=RadioScreens.key(wifi);String priorOther=prefs.text(RadioScreens.key(!wifi),"");main(()->ScreenLearning.start(home,wifi));until(()->active());until(()->home.hasWindowFocus()&&field(home,"headerNotice")!=null);check((ControlService.connected().getServiceInfo().flags&AccessibilityServiceInfo.FLAG_REQUEST_FILTER_KEY_EVENTS)!=0,"Back filter is armed only for explicit capture");main(()->home.startActivity(new Intent(android.provider.Settings.ACTION_SETTINGS).setComponent(target)));until(()->focused(target.getPackageName()));until(()->field(field(ControlService.connected(),"learning"),"candidate")!=null);String beforeTest=prefs.text(key,"");physicalBack();until(()->!active()&&sheet()!=null&&sheet().dialog.getWindow().getDecorView().hasWindowFocus());idle();check(prefs.text(key,"").equals(beforeTest),"recording stops without saving a route");check(prefs.text(RadioScreens.key(!wifi),"").equals(priorOther),"capture does not alter the other radio route");ActionSheet offer=sheet();check(offer.rows.size()==3,"Home offers Test captured screen, manual choice and Cancel");ActivityMonitor test=new ActivityMonitor(RadioScreens.class.getName(),null,false);addMonitor(test);main(()->offer.rows.get(0).performClick());screen=(RadioScreens)waitForMonitorWithTimeout(test,15000);removeMonitor(test);check(screen!=null,"test opens the dedicated route verifier");until(()->focused(target.getPackageName()));check(!active(),"trial screen runs after observation and Back filtering have stopped");shell("input keyevent 4");until(()->sheet()!=null&&screen.hasWindowFocus()==false);ActionSheet confirmation=sheet();check(confirmation.rows.size()==3,"trial return asks whether the correct screen opened");if(save){main(()->confirmation.rows.get(0).performClick());until(()->home.hasWindowFocus());Intent stored=Intent.parseUri(prefs.text(key,""),0);check(target.equals(stored.getComponent()),"explicit confirmation saves the captured accessible system Activity");check((wifi?"android.settings.WIFI_SETTINGS":"android.settings.BLUETOOTH_SETTINGS").equals(stored.getAction()),"stored route retains the requested public Wi-Fi or Bluetooth action");}else{main(()->confirmation.rows.get(1).performClick());until(()->screen.hasWindowFocus());check(prefs.text(key,"").equals(beforeTest),"Choose another rejects the captured route without saving");main(screen::finish);until(()->home.hasWindowFocus());}screen=null;idle();}
 String savedBt=prefs.text("bluetooth_route",""),savedWifi=prefs.text("wifi_route","");main(()->ScreenLearning.start(home,true));until(()->active());ScreenLearning capture=(ScreenLearning)field(ControlService.connected(),"learning");Runnable deadline=(Runnable)field(capture,"timeout");until(()->home.hasWindowFocus());main(deadline);until(()->!active()&&sheet()!=null&&sheet().dialog.getWindow().getDecorView().hasWindowFocus());idle();check(prefs.text("bluetooth_route","").equals(savedBt)&&prefs.text("wifi_route","").equals(savedWifi),"timeout callback leaves both confirmed routes unchanged");main(()->{try{sheet().dialog.dismiss();}catch(Exception e){throw new RuntimeException(e);}});main(()->ScreenLearning.start(home,false));until(()->active());main(()->ControlService.connected().onInterrupt());check(!active(),"service interruption cancels capture");idle();check(field(capture,"candidate")==null,"cancel clears the in-memory window component");Intent probe=new Intent().setClassName("ru.truetv.probe","ru.truetv.probe.Probe");main(()->home.startActivity(probe));until(()->focused("ru.truetv.probe"));main(()->ControlService.connected().begin(home,"ru.truetv.probe",false));until(()->(c.getPackageManager().getApplicationInfo("ru.truetv.probe",0).flags&ApplicationInfo.FLAG_STOPPED)!=0);check(true,"existing selected force-stop still works after capture widened the legacy service package filter");until(()->home.hasWindowFocus());idle();result.putBoolean("passed",true);

 }catch(Throwable t){try{if(ControlService.connected()!=null){Object learner=field(ControlService.connected(),"learning");log.append("DIAG capturing=").append(field(learner,"capturing")).append(" finishing=").append(field(learner,"finishing")).append(" backDown=").append(field(learner,"backDown")).append(" pending=").append(field(learner,"pending")).append(" homeFinishing=").append(home!=null&&home.isFinishing()).append(" sheet=").append(sheet()).append(" seen=").append(field(learner,"seen")).append(" candidate=").append(field(learner,"candidate")).append(" info=").append(ControlService.connected().getServiceInfo()).append("\n");}}catch(Exception ignored){}StringWriter s=new StringWriter();t.printStackTrace(new PrintWriter(s));log.append(s);result.putBoolean("passed",false);}finally{try{if(automation!=null){if(ControlService.connected()!=null){ScreenLearning capture=(ScreenLearning)field(ControlService.connected(),"learning");main(capture::cancel);}ActionSheet current=sheet();if(current!=null)main(current.dialog::dismiss);if(screen!=null)main(screen::finish);if(home!=null)main(home::finish);if(beforeServices!=null)shell(beforeServices.equals("null")?"settings delete secure enabled_accessibility_services":"settings put secure enabled_accessibility_services "+beforeServices);if(beforeEnabled!=null)shell(beforeEnabled.equals("null")?"settings delete secure accessibility_enabled":"settings put secure accessibility_enabled "+beforeEnabled);}if(before!=null){SharedPreferences.Editor e=new SettingsStore(c).data.edit().clear();for(Map.Entry<String,?> x:before.entrySet()){Object v=x.getValue();if(v instanceof String)e.putString(x.getKey(),(String)v);else if(v instanceof Boolean)e.putBoolean(x.getKey(),(Boolean)v);else if(v instanceof Integer)e.putInt(x.getKey(),(Integer)v);else if(v instanceof Long)e.putLong(x.getKey(),(Long)v);}e.commit();}}catch(Exception e){log.append("RESTORE ").append(e);}}result.putString("report",log+"Checks="+checks);finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
